//! The read-only shadow through `Service::init` itself: a read-only service
//! over the disposable bank (PL_SHADOW_REFRESH_DSN) with the tiny ONNX
//! fixture model (PL_SHADOW_EMBED_FIXTURE, generated by
//! `harness/embedding_fixture.py` at 1024 dimensions; ONNX Runtime from
//! ORT_DYLIB_PATH). The service adopts a writer session as its storage,
//! since a read-only session needs the `pseudolife_shadow` role, which the
//! test login cannot create; every path under test is the read-only one,
//! chosen by the service's configuration.

use super::*;
use crate::shadow::tests::{CLEAR, DB, required, test_dsn, vector};

/// The fixture model and the runtime, or `None` to skip (a panic when the
/// database tests are required).
fn fixture_model() -> Option<PathBuf> {
    let model = std::env::var_os("PL_SHADOW_EMBED_FIXTURE").filter(|v| !v.is_empty());
    let runtime = std::env::var_os("ORT_DYLIB_PATH").filter(|v| !v.is_empty());
    match (model, runtime) {
        (Some(model), Some(_)) => Some(PathBuf::from(model)),
        _ if required() => panic!(
            "PL_SHADOW_REFRESH_REQUIRED=1 but PL_SHADOW_EMBED_FIXTURE or ORT_DYLIB_PATH is unset"
        ),
        _ => {
            eprintln!("PL_SHADOW_EMBED_FIXTURE or ORT_DYLIB_PATH unset: skipping service test");
            None
        }
    }
}

struct Shadow {
    service: Arc<Service>,
    side: tokio_postgres::Client,
    side_task: tokio::task::JoinHandle<()>,
    dir: PathBuf,
}

impl Shadow {
    async fn open(dsn: &str, model: &std::path::Path) -> Shadow {
        Shadow::open_with(dsn, model, true).await
    }

    /// The same fixture service in writer mode.
    async fn open_writer(dsn: &str, model: &std::path::Path) -> Shadow {
        Shadow::open_with(dsn, model, false).await
    }

    async fn open_with(dsn: &str, model: &std::path::Path, read_only: bool) -> Shadow {
        let defaults = Config::default();
        let config = Config {
            read_only,
            embedding: crate::config::EmbeddingConfig {
                model_name: "pseudolife-test/shadow-fixture".into(),
                backend: "onnx".into(),
                ..defaults.embedding.clone()
            },
            ..defaults
        };
        let dir = std::env::temp_dir().join(format!(
            "pl-shadow-service-{}-{}",
            std::process::id(),
            uuid::Uuid::new_v4()
        ));
        std::fs::create_dir_all(&dir).unwrap();
        let service = Arc::new(Service::new(
            config,
            DaemonEnv::from_env(&|_| None).unwrap(),
            dir.clone(),
            dsn.to_string(),
            false,
        ));
        assert_eq!(service.config.read_only, read_only);
        // What `install` sets at startup.
        let _ = service.handle.set(Arc::downgrade(&service));
        let storage = Arc::new(Storage::open(dsn).await.unwrap());
        storage.client().batch_execute(CLEAR).await.unwrap();
        let embedder = Embedder::load_config(&service.config.embedding, Some(model), 1).unwrap();
        assert_eq!(embedder.embedding_dim(), crate::bank::DIM);
        {
            let mut inner = service.inner.lock().await;
            inner.storage = Some(storage.clone());
            inner.embedder = Some(Arc::new(embedder));
        }
        service.update(|s| s.storage = Some(storage));
        let (side, side_task) = crate::storage::connect(
            &crate::storage::parse_dsn(dsn).unwrap(),
            std::time::Duration::from_secs(10),
        )
        .await
        .unwrap();
        Shadow {
            service,
            side,
            side_task,
            dir,
        }
    }

    async fn exec(&self, sql: &str) {
        self.side.batch_execute(sql).await.unwrap();
    }

    async fn insert(&self, text: &str, k: usize) -> i64 {
        self.side
            .query_one(
                "INSERT INTO entries (band, text, embedding, ts, source) \
                 VALUES ('flat', $1, $2::text::vector, $3, 'user') RETURNING id",
                &[&text, &vector(k), &(1000.0 + k as f64)],
            )
            .await
            .unwrap()
            .get(0)
    }

    /// The resident bank equals a fresh hydration, order included, and
    /// holds every id once.
    async fn assert_bank_matches(&self, ready: &Ready) {
        let raw = crate::startup::metadata(&self.side).await.unwrap();
        let (fresh, _) = crate::startup::candidate(
            &self.side,
            &self.service.config.memory,
            raw,
            crate::bank::DIM,
        )
        .await
        .unwrap();
        let bank = ready.bank.read().unwrap();
        let ids: Vec<i64> = bank.entries.iter().map(|e| e.id).collect();
        let unique: std::collections::BTreeSet<i64> = ids.iter().copied().collect();
        assert_eq!(
            ids.len(),
            unique.len(),
            "a resident entry is duplicated: {ids:?}"
        );
        assert_eq!(bank.entries_dump(), fresh.entries_dump());
        assert_eq!(ids, fresh.entries.iter().map(|e| e.id).collect::<Vec<_>>());
        assert_eq!(bank.matrix, fresh.matrix);
    }

    async fn close(self) {
        let storage = self.service.inner.lock().await.storage.take();
        self.service.update(|s| {
            s.storage = None;
            s.ready = None;
            s.startup = None;
        });
        self.service.inner.lock().await.ready = None;
        drop(self.side);
        let _ = self.side_task.await;
        // Closed now, releasing the writer lease before the next test opens.
        if let Some(storage) = storage {
            Arc::try_unwrap(storage)
                .ok()
                .expect("a ready service still holds the session")
                .close()
                .await;
        }
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

/// A request dropped while its refresh's bank patch runs must not release
/// the service lock under that patch: a second refresh would plan from the
/// old state and patch again (duplicate appends, older telemetry last).
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn db_dropped_request_cannot_let_two_refreshes_overlap() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let shadow = Shadow::open(&dsn, &model).await;
    let alpha = shadow.insert("alpha", 1).await;
    shadow.insert("beta", 2).await;
    shadow.service.ensure_init_inner().await.unwrap();
    // The writer's read path and an addition.
    shadow
        .exec(&format!(
            "UPDATE entries SET access_count = 5 WHERE id = {alpha}"
        ))
        .await;
    shadow.insert("gamma", 3).await;
    let (reached, patch_pending) = tokio::sync::oneshot::channel();
    let (release, released) = tokio::sync::oneshot::channel();
    *shadow.service.patch_gate.lock().unwrap() = Some((reached, released));
    // Past the probe reuse, so the awareness read probes and refreshes.
    tokio::time::sleep(SHADOW_PROBE_REUSE + Duration::from_millis(100)).await;
    let service = shadow.service.clone();
    let caller = tokio::spawn(async move { service.ready_if_initialized().await });
    tokio::time::timeout(Duration::from_secs(30), patch_pending)
        .await
        .expect("the refresh never reached its bank patch")
        .unwrap();
    // The client goes away while the patch is pending.
    caller.abort();
    let _ = caller.await;
    let service = shadow.service.clone();
    let mut second = tokio::spawn(async move { service.refresh_writer_session().await });
    let overlapped = tokio::time::timeout(Duration::from_secs(2), &mut second)
        .await
        .is_ok();
    release.send(()).unwrap();
    assert!(
        !overlapped,
        "a second refresh ran while the first one's bank patch was pending"
    );
    let ready = second.await.unwrap().unwrap();
    shadow.assert_bank_matches(&ready).await;
    // The recorded state matches the bank: nothing further to do.
    let again = shadow.service.refresh_writer_session().await.unwrap();
    assert!(
        Arc::ptr_eq(&again, &ready),
        "a settled shadow refreshed again"
    );
    drop((again, ready));
    shadow.close().await;
}

/// A failed version and meta pre-read is a retryable initialization
/// failure: recorded as not_ready, with the backoff armed.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_failed_preread_records_not_ready_and_backs_off() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let shadow = Shadow::open(&dsn, &model).await;
    struct Fault;
    impl Drop for Fault {
        fn drop(&mut self) {
            crate::shadow::PREREAD_FAULT.store(false, std::sync::atomic::Ordering::SeqCst);
        }
    }
    crate::shadow::PREREAD_FAULT.store(true, std::sync::atomic::Ordering::SeqCst);
    let fault = Fault;
    let error = shadow.service.ensure_init_inner().await.err().unwrap();
    assert!(
        error.contains("version and meta pre-read failed: injected pre-read fault"),
        "{error}"
    );
    assert_eq!(
        shadow.service.snapshot().not_ready.as_deref(),
        Some(error.as_str())
    );
    let retry = shadow.service.ensure_init_inner().await.err().unwrap();
    assert!(retry.contains("next retry in"), "no backoff armed: {retry}");
    drop(fault);
    shadow.close().await;
}

/// A meta commit after `Service::init`'s own read of meta, before its
/// hydration, is caught by the next refresh (the cortex included).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_meta_commit_during_service_init_is_refreshed() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let shadow = Shadow::open(&dsn, &model).await;
    shadow.insert("alpha", 1).await;
    let (release, gate) = tokio::sync::oneshot::channel();
    *shadow.service.preread_gate.lock().unwrap() = Some(gate);
    let service = shadow.service.clone();
    let init = tokio::spawn(async move { service.ensure_init().await });
    let deadline = Instant::now() + Duration::from_secs(30);
    while shadow.service.preread_gate.lock().unwrap().is_some() {
        assert!(Instant::now() < deadline, "init never read meta");
        tokio::time::sleep(Duration::from_millis(10)).await;
    }
    shadow
        .exec(
            "INSERT INTO meta (key, value) VALUES ('cortex_dream_cursor', '12.5'), \
             ('active_session_pointer', '{\"session_id\": \"s3\", \"ts\": 7}')",
        )
        .await;
    release.send(()).unwrap();
    let first = init.await.unwrap().unwrap();
    assert_eq!(
        first.startup.metadata["cortex_dream_cursor"],
        serde_json::json!(0.0),
        "init hydrated meta it had not read"
    );
    let ready = shadow.service.refresh_writer_session().await.unwrap();
    assert_eq!(
        ready.startup.metadata["cortex_dream_cursor"],
        serde_json::json!(12.5),
        "the meta commit during init was never refreshed"
    );
    assert_eq!(
        ready.startup.metadata["active_session"],
        serde_json::json!(["s3", 7.0])
    );
    assert_eq!(ready.cortex.snapshot().dream_cursor, 12.5);
    drop((first, ready));
    shadow.close().await;
}

/// A writer whose COMMIT reply was lost: the bank holds `lost`, which the
/// resident copy never published.
async fn lose_a_commit(shadow: &Shadow, text: &str, k: usize) -> i64 {
    let id = shadow.insert(text, k).await;
    crate::txn::set_commit_outcome_unknown_for_test(true);
    id
}

fn resident_ids(ready: &Ready) -> Vec<i64> {
    ready
        .bank
        .read()
        .unwrap()
        .entries
        .iter()
        .map(|e| e.id)
        .collect()
}

/// A commit-unknown re-read waits for the write already holding the
/// resident copy's writer mutex, so what that write commits is in the copy
/// the re-read publishes rather than lost under it.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn db_commit_unknown_reread_waits_for_the_write_in_flight() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let _flag = crate::txn::tests::TESTS.lock().await;
    crate::txn::set_commit_outcome_unknown_for_test(false);
    let shadow = Shadow::open_writer(&dsn, &model).await;
    shadow.insert("alpha", 1).await;
    let ready = shadow.service.ensure_init_inner().await.unwrap();
    // A write is in flight: it holds the writer mutex when the flag sets.
    let in_flight = ready.write.lock().await;
    let lost = lose_a_commit(&shadow, "lost", 2).await;
    let (reached, read_done) = tokio::sync::oneshot::channel();
    let (release, released) = tokio::sync::oneshot::channel();
    *shadow.service.reread_gate.lock().unwrap() = Some((reached, released));
    let service = shadow.service.clone();
    let call = tokio::spawn(async move { service.ensure_init_inner().await });
    let read_early = tokio::time::timeout(Duration::from_secs(2), read_done).await;
    // The write in flight commits and releases the mutex.
    let in_flight_id = shadow.insert("in flight", 3).await;
    drop(in_flight);
    release.send(()).unwrap();
    let after = call.await.unwrap().unwrap();
    assert!(
        read_early.is_err(),
        "the re-read read the bank while a write still held the writer mutex"
    );
    assert!(Arc::ptr_eq(&after, &ready), "re-read in place");
    let ids = resident_ids(&after);
    assert!(ids.contains(&lost), "the lost commit is resident");
    assert!(
        ids.contains(&in_flight_id),
        "the write in flight is resident"
    );
    shadow.assert_bank_matches(&after).await;
    assert!(!crate::txn::commit_outcome_unknown());
    drop((ready, after));
    shadow.close().await;
}

/// A re-read that fails answers the call with an error and leaves the flag
/// set, so the next call re-reads rather than serve the stale copy.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_failed_commit_unknown_reread_keeps_the_flag() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let _flag = crate::txn::tests::TESTS.lock().await;
    crate::txn::set_commit_outcome_unknown_for_test(false);
    let shadow = Shadow::open_writer(&dsn, &model).await;
    shadow.insert("alpha", 1).await;
    let ready = shadow.service.ensure_init_inner().await.unwrap();
    let lost = lose_a_commit(&shadow, "lost", 2).await;
    shadow
        .service
        .reread_fails
        .store(true, std::sync::atomic::Ordering::SeqCst);
    let Err(error) = shadow.service.ensure_init_inner().await else {
        panic!("the call was served from the stale copy");
    };
    assert!(error.contains("commit outcome is unknown"), "{error}");
    assert!(
        crate::txn::commit_outcome_unknown(),
        "a failed re-read leaves the flag set"
    );
    assert!(!resident_ids(&ready).contains(&lost));
    let after = shadow.service.ensure_init_inner().await.unwrap();
    assert!(
        resident_ids(&after).contains(&lost),
        "the next call re-read the bank"
    );
    shadow.assert_bank_matches(&after).await;
    assert!(!crate::txn::commit_outcome_unknown());
    drop((ready, after));
    shadow.close().await;
}

/// The re-read rebuilds what a cold start reads from the bank (here the
/// active session, part of the episode state) and keeps what only this
/// process holds (an access count searches accrued since the last autosave).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_commit_unknown_reread_keeps_access_counts_and_rereads_episodes() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let _flag = crate::txn::tests::TESTS.lock().await;
    crate::txn::set_commit_outcome_unknown_for_test(false);
    let shadow = Shadow::open_writer(&dsn, &model).await;
    let alpha = shadow.insert("alpha", 1).await;
    let ready = shadow.service.ensure_init_inner().await.unwrap();
    let count = |ready: &Ready| {
        ready
            .bank
            .read()
            .unwrap()
            .entries
            .iter()
            .find(|e| e.id == alpha)
            .map(|e| e.access_count.load(std::sync::atomic::Ordering::Relaxed))
    };
    {
        let bank = ready.bank.read().unwrap();
        let entry = bank.entries.iter().find(|e| e.id == alpha).unwrap();
        entry
            .access_count
            .store(7, std::sync::atomic::Ordering::Relaxed);
    }
    ready.write.lock().await.active_session = Some(("ghost".into(), 1.0));
    lose_a_commit(&shadow, "lost", 2).await;
    let after = shadow.service.ensure_init_inner().await.unwrap();
    assert_eq!(count(&after), Some(7), "an unsynced access count survives");
    assert_eq!(
        after.write.lock().await.active_session,
        None,
        "the episode state is re-read from the bank"
    );
    assert!(
        shadow
            .service
            .counters_pending
            .load(std::sync::atomic::Ordering::SeqCst),
        "the next autosave syncs the kept counts"
    );
    drop((ready, after));
    shadow.close().await;
}

/// A cortex change no call saved is persisted by the next autosave, as
/// Python's `autosave_if_changed` saves the cortex (`_persist_all` ->
/// `_save_cortex`): the forget cascade's retirement, whose supersession-log
/// row only the resident store holds once the cascade's transaction retired
/// the facts row, and a write whose own save failed, which stays in the
/// store and dirty. An autosave with nothing dirty writes nothing.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_autosave_saves_dirty_canonical_slots() {
    use crate::background::Duties;
    use crate::stores::cortex_write::FactWrite;
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let shadow = Shadow::open_writer(&dsn, &model).await;
    let ready = shadow.service.ensure_init_inner().await.unwrap();
    let embedding: Arc<[f32]> = {
        let mut v = vec![0.0f32; crate::bank::DIM];
        v[0] = 1.0;
        v.into()
    };
    let fact = |entity: &'static str, value: &'static str, t: f64| FactWrite {
        entity,
        attribute: "engine",
        value,
        raw: serde_json::Map::new(),
        embedding: embedding.clone(),
        slot_embedding: Some(embedding.clone()),
        confidence: 1.0,
        support: Some("user"),
        now: t,
        hlc: ((t * 1000.0) as i64, 0),
        writer_id: Some("autosave-test".into()),
        session_id: None,
        freshness_class: "evergreen".into(),
        authority: crate::labels::Resolved::Inherit,
        distortion_tolerance: crate::labels::Resolved::Inherit,
        provenance: Vec::new(),
        stance: None,
        force_contend: false,
        dream: false,
    };
    // A current value, saved as `memory_fact_set` saves it.
    ready
        .cortex
        .write(|s| s.write_fact(&fact("hosta", "postgres", 1000.0)))
        .unwrap();
    crate::fact_set::save_cortex(&shadow.service, &ready)
        .await
        .unwrap();
    shadow.service.autosave().await.unwrap();
    // The forget cascade: its transaction retires the row, then the
    // resident store retires the value and logs it, with no save.
    shadow
        .exec(
            "UPDATE facts SET status = 'retired', superseded_at = 2000, \
             superseded_by_value = 'forgotten source entry 7' \
             WHERE entity_norm = 'hosta' AND status = 'current'",
        )
        .await;
    let retired = ready
        .cortex
        .write(|c| c.retire_unsupported("hosta", "engine", 7, 2000.0));
    assert_eq!(retired, 1);
    // A write whose save failed: in the store, dirty, not in the bank.
    ready
        .cortex
        .write(|s| s.write_fact(&fact("hostb", "mysql", 2001.0)))
        .unwrap();
    shadow.service.autosave().await.unwrap();
    let log: Option<serde_json::Value> = shadow
        .side
        .query_opt(
            "SELECT value FROM meta WHERE key = 'cortex_supersession_log'",
            &[],
        )
        .await
        .unwrap()
        .map(|r| r.get(0));
    let last = log
        .as_ref()
        .and_then(|l| l.as_array())
        .and_then(|l| l.last())
        .cloned();
    assert_eq!(
        last.as_ref()
            .map(|r| (r["decision"].clone(), r["reason"].clone())),
        Some((
            serde_json::json!("retired"),
            serde_json::json!("forgotten source entry 7")
        )),
        "the autosave persisted the cascade's retirement log row: {log:?}"
    );
    let rows: i64 = shadow
        .side
        .query_one(
            "SELECT count(*) FROM facts WHERE entity_norm = 'hostb' \
             AND value = 'mysql' AND status = 'current'",
            &[],
        )
        .await
        .unwrap()
        .get(0);
    assert_eq!(rows, 1, "the autosave persisted the unsaved write");
    {
        let snap = ready.cortex.snapshot();
        assert!(snap.dirty_slots.is_empty() && !snap.meta_dirty);
    }
    // Nothing dirty and nothing changed: a row edited behind the daemon's
    // back stays as written.
    shadow
        .exec("UPDATE facts SET value = 'behind' WHERE entity_norm = 'hostb'")
        .await;
    shadow.service.autosave().await.unwrap();
    let value: String = shadow
        .side
        .query_one("SELECT value FROM facts WHERE entity_norm = 'hostb'", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(value, "behind", "an idle autosave wrote the cortex");
    drop(ready);
    shadow.close().await;
}

/// The world-store write [`db_autosave_waits_for_the_commit_unknown_reread`]
/// and [`db_autosave_retries_a_failed_world_save`] make.
fn world_write(now: f64) -> crate::stores::world::WorldWrite<'static> {
    crate::stores::world::WorldWrite {
        confidence: 0.85,
        source_url: "https://example.com/acme",
        source_quote: "",
        freshness_class: "volatile",
        retrieved_at: None,
        content_hash: None,
        source_doc_id: None,
        now,
        hlc: ((now * 1000.0) as i64, 0),
        writer_id: Some("autosave-test"),
        session_id: None,
    }
}

async fn world_status(shadow: &Shadow, entity_norm: &str) -> Vec<(String, String)> {
    shadow
        .side
        .query(
            "SELECT value, status FROM world_facts WHERE entity_norm = $1 ORDER BY id",
            &[&entity_norm],
        )
        .await
        .unwrap()
        .iter()
        .map(|r| (r.get(0), r.get(1)))
        .collect()
}

/// A legacy world restore whose COMMIT reply was lost: the bank holds the
/// restore (`acme`/`ceo` current), the resident store is undone to retired,
/// and the slot keeps the dirty mark it had before the restore; the
/// commit-unknown flag is set. The caller holds `txn::tests::TESTS`.
async fn undone_committed_restore(shadow: &Shadow, ready: &Ready) {
    // A retired value, saved.
    ready.world.write(|s| {
        s.write_fact("acme", "ceo", "jane", None, &world_write(1000.0));
        s.retire("acme", Some("ceo"), 1500.0);
    });
    crate::world_tools::save_world(&shadow.service, ready)
        .await
        .unwrap();
    assert_eq!(
        world_status(shadow, "acme").await,
        vec![("jane".into(), "retired".into())]
    );
    // The slot is dirty before the restore (an earlier save of it failed).
    let key = ready.world.snapshot().records[0].key.clone();
    ready.world.write(|s| s.dirty_slots.insert(key.clone()));
    let marks: Vec<(usize, Option<f64>, bool)> = {
        let snap = ready.world.snapshot();
        snap.restore_picks("acme", Some("ceo"))
            .into_iter()
            .map(|i| (i, snap.records[i].superseded_at, true))
            .collect()
    };
    ready.world.write(|s| s.restore("acme", Some("ceo")));
    // The restore's transaction committed; its reply was lost.
    shadow
        .exec(
            "UPDATE world_facts SET status = 'current', superseded_at = NULL \
             WHERE entity_norm = 'acme'",
        )
        .await;
    crate::txn::set_commit_outcome_unknown_for_test(true);
    ready.world.write(|s| s.undo_restore(&marks));
    assert!(ready.world.snapshot().dirty_slots.contains(&key));
}

/// A legacy world restore whose COMMIT reply was lost: the bank holds the
/// restore, the resident store is undone to retired, and the slot keeps the
/// dirty mark it had before the restore. The autosave must not flush that
/// slot before the commit-unknown re-read (which the next call runs) has
/// replaced the resident stores, or it writes the retired state over the
/// restore that committed.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_autosave_waits_for_the_commit_unknown_reread() {
    use crate::background::Duties;
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let _flag = crate::txn::tests::TESTS.lock().await;
    crate::txn::set_commit_outcome_unknown_for_test(false);
    let shadow = Shadow::open_writer(&dsn, &model).await;
    let ready = shadow.service.ensure_init_inner().await.unwrap();
    undone_committed_restore(&shadow, &ready).await;
    // An autosave tick before the next call.
    let _ = shadow.service.autosave().await;
    assert_eq!(
        world_status(&shadow, "acme").await,
        vec![("jane".into(), "current".into())],
        "the autosave wrote the undone resident slot over the committed restore"
    );
    assert!(crate::txn::commit_outcome_unknown());
    // The next call re-reads the bank; the autosave after it writes nothing.
    let after = shadow.service.ensure_init_inner().await.unwrap();
    assert!(!crate::txn::commit_outcome_unknown());
    assert!(after.world.snapshot().dirty_slots.is_empty());
    shadow.service.autosave().await.unwrap();
    assert_eq!(
        world_status(&shadow, "acme").await,
        vec![("jane".into(), "current".into())]
    );
    crate::txn::set_commit_outcome_unknown_for_test(false);
    drop((ready, after));
    shadow.close().await;
}

/// A world-store save the bank refuses leaves its slot dirty and answers
/// the autosave with the failure; the next autosave retries it and, the
/// refusal gone, persists it, as Python's next autosave retries a failed
/// `_save_world`.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_autosave_retries_a_failed_world_save() {
    use crate::background::Duties;
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let shadow = Shadow::open_writer(&dsn, &model).await;
    let ready = shadow.service.ensure_init_inner().await.unwrap();
    shadow
        .exec(
            "ALTER TABLE world_facts ADD CONSTRAINT autosave_test_refusal \
             CHECK (entity_norm <> 'globex')",
        )
        .await;
    ready
        .world
        .write(|s| s.write_fact("globex", "ceo", "hank", None, &world_write(1000.0)));
    let failed = shadow.service.autosave().await;
    shadow
        .exec("ALTER TABLE world_facts DROP CONSTRAINT autosave_test_refusal")
        .await;
    let failed = failed.expect_err("a refused world save fails the autosave");
    assert!(failed.contains("world cortex"), "{failed}");
    assert!(world_status(&shadow, "globex").await.is_empty());
    assert!(!ready.world.snapshot().dirty_slots.is_empty());
    shadow.service.autosave().await.unwrap();
    assert_eq!(
        world_status(&shadow, "globex").await,
        vec![("hank".into(), "current".into())],
        "the next autosave retried the failed save"
    );
    assert!(ready.world.snapshot().dirty_slots.is_empty());
    drop(ready);
    shadow.close().await;
}

/// The sweep's compaction honours the same commit-unknown barrier as the
/// autosave: the sweep drops the service lock after its init, so a write
/// can lose its COMMIT before the compaction runs, and saving the stores'
/// dirty slots then writes the undone restore over the committed one.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_compaction_waits_for_the_commit_unknown_reread() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let _flag = crate::txn::tests::TESTS.lock().await;
    crate::txn::set_commit_outcome_unknown_for_test(false);
    let shadow = Shadow::open_writer(&dsn, &model).await;
    let ready = shadow.service.ensure_init_inner().await.unwrap();
    undone_committed_restore(&shadow, &ready).await;
    // A compaction that purges nothing still saves any dirty slot.
    shadow.service.compact_superseded(&ready, 1000, 1.0e9).await;
    assert_eq!(
        world_status(&shadow, "acme").await,
        vec![("jane".into(), "current".into())],
        "the compaction wrote the undone resident slot over the committed restore"
    );
    assert!(crate::txn::commit_outcome_unknown());
    let after = shadow.service.ensure_init_inner().await.unwrap();
    assert!(!crate::txn::commit_outcome_unknown());
    shadow.service.compact_superseded(&after, 1000, 1.0e9).await;
    assert_eq!(
        world_status(&shadow, "acme").await,
        vec![("jane".into(), "current".into())]
    );
    crate::txn::set_commit_outcome_unknown_for_test(false);
    drop((ready, after));
    shadow.close().await;
}

/// The sweep's compaction when the cortex save loses its COMMIT reply
/// mid-tick: the world and lesson stores are neither compacted nor saved
/// after it, so no reader sees a purge the bank never got and nothing is
/// written before the re-read. The reply is lost for real: a deferred
/// constraint trigger on `facts` refuses the COMMIT, and any COMMIT error
/// leaves the outcome unknown (`txn::run`).
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn db_compaction_stops_after_a_save_loses_its_commit() {
    let Some(dsn) = test_dsn() else { return };
    let Some(model) = fixture_model() else { return };
    let _guard = DB.lock().await;
    let _flag = crate::txn::tests::TESTS.lock().await;
    crate::txn::set_commit_outcome_unknown_for_test(false);
    let shadow = Shadow::open_writer(&dsn, &model).await;
    let ready = shadow.service.ensure_init_inner().await.unwrap();
    // A retired world value and a retired lesson, saved: both are purged by
    // a compaction that keeps no non-live record.
    ready.world.write(|s| {
        s.write_fact("acme", "ceo", "jane", None, &world_write(1000.0));
        s.retire("acme", Some("ceo"), 1500.0);
    });
    crate::world_tools::save_world(&shadow.service, &ready)
        .await
        .unwrap();
    let lesson = crate::stores::lessons::LessonWrite {
        about: None,
        outcome: "success",
        polarity: "+",
        confidence: 0.6,
        origin: Some("agent"),
        provenance: &[],
        support: &[],
        now: 1000.0,
        hlc: Some((1_000_000, 0)),
        valid_time: None,
        writer_id: None,
        session_id: None,
    };
    ready.lessons.write(|s| {
        s.write_fact("deploy", "approach", "use the pipeline", None, &lesson);
        s.retire("deploy", Some("approach"), 1500.0);
    });
    crate::forget_tools::save_lessons(&shadow.service, &ready)
        .await
        .unwrap();
    // An unsaved cortex write, whose save the compaction makes.
    let embedding: Arc<[f32]> = {
        let mut v = vec![0.0f32; crate::bank::DIM];
        v[0] = 1.0;
        v.into()
    };
    ready
        .cortex
        .write(|s| {
            s.write_fact(&crate::stores::cortex_write::FactWrite {
                entity: "hostc",
                attribute: "engine",
                value: "sqlite",
                raw: serde_json::Map::new(),
                embedding: embedding.clone(),
                slot_embedding: Some(embedding.clone()),
                confidence: 1.0,
                support: Some("user"),
                now: 2000.0,
                hlc: (2_000_000, 0),
                writer_id: Some("autosave-test".into()),
                session_id: None,
                freshness_class: "evergreen".into(),
                authority: crate::labels::Resolved::Inherit,
                distortion_tolerance: crate::labels::Resolved::Inherit,
                provenance: Vec::new(),
                stance: None,
                force_contend: false,
                dream: false,
            })
        })
        .unwrap();
    shadow
        .exec(
            "CREATE FUNCTION autosave_test_refuse_commit() RETURNS trigger \
             LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'refused at commit'; END $$; \
             CREATE CONSTRAINT TRIGGER autosave_test_refuse_commit AFTER INSERT ON facts \
             DEFERRABLE INITIALLY DEFERRED FOR EACH ROW \
             EXECUTE FUNCTION autosave_test_refuse_commit();",
        )
        .await;
    shadow.service.compact_superseded(&ready, 0, 0.0).await;
    shadow
        .exec(
            "DROP TRIGGER autosave_test_refuse_commit ON facts; \
             DROP FUNCTION autosave_test_refuse_commit();",
        )
        .await;
    assert!(
        crate::txn::commit_outcome_unknown(),
        "the cortex save's refused COMMIT leaves the outcome unknown"
    );
    let world = ready.world.snapshot();
    let lessons = ready.lessons.snapshot();
    assert_eq!(
        (world.records.len(), lessons.records.len()),
        (1, 1),
        "the world or lesson store was compacted after the cortex save lost its COMMIT"
    );
    assert!(world.dirty_slots.is_empty() && lessons.dirty_slots.is_empty());
    assert_eq!(
        world_status(&shadow, "acme").await,
        vec![("jane".into(), "retired".into())]
    );
    let lesson_rows: i64 = shadow
        .side
        .query_one("SELECT count(*) FROM lessons", &[])
        .await
        .unwrap()
        .get(0);
    assert_eq!(lesson_rows, 1);
    crate::txn::set_commit_outcome_unknown_for_test(false);
    drop((world, lessons, ready));
    shadow.close().await;
}
